"use strict";

// The same defect in a STATEMENT HEADER: an `if` condition.
//
//     if (bail()) { ... }
//
// The test expression is evaluated by the act of reaching the statement,
// before either arm can run, so nothing about the branch bodies needs to
// be modeled for the module evaluation to end here. A `switch`
// discriminant, a `while` condition, a `for` initializer and test, and a
// `for-of`/`for-in` right-hand side are all the same shape; this module
// carries the `if` form, and `positions.js` in the ground-truth fixture
// measures all of them.
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("fast mode is not supported here");
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  if (bail()) {
    void 0;
  }
}

module.exports = safeOp;
